final:
def fact(n: int) -> int:
    """Return n! for n >= 0.

    Raises ValueError when n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small() -> None:
    assert fact(5) == 120


def test_fact_grows() -> None:
    assert fact(10) == 3628800


def test_fact_negative_raises() -> None:
    import pytest

    with pytest.raises(ValueError):
        fact(-1)
